INSERT INTO scenario_question_language_variant (
    id, scenario_question_id, target_locale, base_locale, question_text,
    question_translation, audio_url, status, created_at, updated_at,
    inner_thought, inner_thought_type
) VALUES
(121, 121, 'EN', 'KR', 'Hi! I''m Marco. What''s your name?', '안녕! 난 Marco야. 이름이 뭐야?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/121/53312298df78ccb3087eb2225df1ce78d0b5200da57cc88f97c3dada829baee3.mp3', 'ACTIVE', now(), now(), '먼저 이름을 물으면 편하게 대화를 시작할 수 있겠다.', 'GOOD'),
(122, 122, 'EN', 'KR', 'What''s your hobby?', '넌 취미가 뭐야?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/122/175fbe11724bee91c7b3264cc4244d05f8b984908eea12e3fb7ffabbdc8bdd43.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(123, 123, 'EN', 'KR', 'I want to visit Korea. What''s your favorite place there?', '나 한국에 가보고 싶어. 넌 한국에서 어떤 곳을 좋아해?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/123/9bb58adedff0236418ee3ac6b9733b0c65dd3dd3726d3c02c8cf6549a7b2553e.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(124, 124, 'EN', 'KR', 'Nice to meet you! I''m Marco. Could you tell me a little about yourself?', '만나서 반가워! 난 Marco야. 네 소개를 간단히 해줄래?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/124/4e90ea1e70e875fe4964047d356480ec9c1d69d7d0af4070d89299112235bbdc.mp3', 'ACTIVE', now(), now(), '간단한 자기소개를 부탁하면 서로를 자연스럽게 알아갈 수 있겠다.', 'GOOD'),
(125, 125, 'EN', 'KR', 'What''s your hobby? What do you like about it?', '넌 취미가 뭐야? 그 취미의 어떤 점이 좋아?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/125/0c0b93de58fd33a0db4fecfae91ea886d8f8cf6f4d7e58c84a3fdaf430e45bdb.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(126, 126, 'EN', 'KR', 'If I visit Korea, what place should I see first?', '내가 한국에 가면 어디를 먼저 가보면 좋을까?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/126/9aa104335134f028c9784e5b6299528e415a7b4389f79a3e1004b9f6a786a461.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(127, 127, 'EN', 'KR', 'Do you like washing dishes or cleaning the floor?', '설거지와 바닥 청소 중 뭐가 더 좋아?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/127/cc7551db4104785e152cf7e6c5fcd557e44b648add6fc26cfa5632c893c7afd5.mp3', 'ACTIVE', now(), now(), '좋아하는 집안일부터 물으면 역할을 쉽게 나눌 수 있겠다.', 'GOOD'),
(128, 128, 'EN', 'KR', 'When should we clean our room?', '우리 방은 언제 청소할까?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/128/4e7a5f4f4a7dadbaa05a74b7195282aa7a8ef80bd9baba71db3af1db669cb0df.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(129, 129, 'EN', 'KR', 'Do you sleep early or late?', '너는 일찍 자, 늦게 자?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/129/52121c4a94d7194e5c1ffcdcaaad72d5060587fc3469702abeb390949e27aefa.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(130, 130, 'EN', 'KR', 'Which chores do you prefer? I can wash dishes or clean the floor.', '어떤 집안일이 더 편해? 나는 설거지나 바닥 청소를 할 수 있어.', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/130/2e28bfaa67d6d0a264c519c40c2c9ffda345bb618904f73a112143a840a2ee2c.mp3', 'ACTIVE', now(), now(), '각자 편한 집안일을 말하면 공평하게 나눌 수 있겠다.', 'GOOD'),
(131, 131, 'EN', 'KR', 'How often should we clean the room, and which day works best?', '방을 얼마나 자주 청소하고, 어느 날 하는 게 좋을까?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/131/cfa6af1ae68200a94381a8e6d988b39b3bcbae42e957a6a8c0d3fc8cd58e927f.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(132, 132, 'EN', 'KR', 'I''m often awake late. What time should quiet hours start? I can take phone calls outside after that.', '나는 자주 늦게까지 깨어 있어. 몇 시부터 조용히 하면 좋을까? 그 뒤에는 전화도 밖에서 받을게.', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/132/bb8022761a791f390fddd9ec4fa3a3e4c03bb7f9e828c05d4074144e3a00160b.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(133, 133, 'EN', 'KR', 'Let''s meet this weekend! Is Saturday or Sunday better?', '이번 주말에 만나자! 토요일이 좋아, 일요일이 좋아?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/133/5ef9773f0b4464872fe247fa0b2b9571436802dbfa5c49e73b02a2a558119e2d.mp3', 'ACTIVE', now(), now(), '토요일과 일요일 중 하나를 고르게 하면 약속을 쉽게 시작할 수 있겠다.', 'GOOD'),
