(275, 275, 'EN', 'KR', 'Would you like the ticket printed or sent to your phone?', '표를 출력해 드릴까요, 휴대폰으로 보내드릴까요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/275/fec1b7ed285d4ce03247e4f9742ceece0be10659c47787e009238cfe585d91a5.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(276, 276, 'EN', 'KR', 'Window and aisle seats are available. Tell me your seat preference.', '창가와 통로 좌석이 남아 있어요. 원하는 좌석을 말씀해 주세요.', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/276/4a6edaa397c506c0e1cdb72dc6a0f3a29c1f50250b474ff96bd0b60b4ed14004.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(277, 277, 'EN', 'KR', 'The pasta is not spicy. The curry is spicy. Which one do you want?', '파스타는 맵지 않고 커리는 매워요. 어떤 걸 원하세요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/277/e169f4931e114047e2ade5f406cf55c7d24da35cff1ba5bfcc9ce05f1ffbd72d.mp3', 'ACTIVE', now(), now(), '부드러운 음식과 매운 음식을 알려주면 쉽게 고를 수 있겠다.', 'GOOD'),
(278, 278, 'EN', 'KR', 'Do you want to add chicken or extra vegetables?', '닭고기나 채소를 더 추가하시겠어요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/278/bd08fd5bbff53a68d74fee99571551b0065a30dda1c6180145fc71bb2695b6b1.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(279, 279, 'EN', 'KR', 'Write a review and get a free side. Do you want to join?', '리뷰를 쓰면 사이드 메뉴가 무료예요. 참여하시겠어요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/279/09f29aa629517a128abad2ac184b140b98c5b4bde2e39685b4c4c6bf5b9fee26.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(280, 280, 'EN', 'KR', 'The pasta is mild and creamy, while the curry is hot and spicy. Which sounds better today?', '파스타는 부드럽고 크리미하고, 커리는 맵고 진해요. 오늘은 어떤 게 더 당기세요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/280/b76f34a8893dfe49f5b14850a1857edfb712cce51309cdf12087be8b3bf8d85a.mp3', 'ACTIVE', now(), now(), '두 메뉴의 맛을 먼저 설명하면 손님이 편하게 선택할 수 있겠다.', 'GOOD'),
(281, 281, 'EN', 'KR', 'You can add chicken or extra vegetables to either dish. Would you like to add one?', '두 메뉴 모두 닭고기나 채소를 더 추가할 수 있어요. 하나 추가하시겠어요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/281/162ae5617d1a9e77afeafa34ae9db85562fb886e53c677ceef99818ca0a27577.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(282, 282, 'EN', 'KR', 'If you leave a review, you can choose a free salad or rice. Would you like to join?', '리뷰를 남기면 샐러드나 밥을 무료로 고를 수 있어요. 참여하시겠어요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/282/4b29cd3b896ff255360447da8967b55a056ca4a9214925cbaaa774afa0b30980.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(283, 283, 'EN', 'KR', 'The museum pass lets you visit two museums. The city pass also includes buses. Which do you want?', '박물관 패스는 박물관 두 곳에 갈 수 있어요. 도시 패스는 버스도 탈 수 있어요. 어떤 걸 원하세요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/283/55841132b404d26992a250049d7a9df283bbf5fc7a52311c6c9ccfee58e24f05.mp3', 'ACTIVE', now(), now(), '두 패스의 차이를 짧게 알려주면 쉽게 고를 수 있겠다.', 'GOOD'),
(284, 284, 'EN', 'KR', 'You can add lunch for $15. Do you want it?', '15달러를 추가하면 점심도 포함할 수 있어요. 추가하시겠어요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/284/c558f75c6bc6066e6a6669a2c5b942cee948a550bd2bb316e262b6a3f3d88257.mp3', 'ACTIVE', now(), now(), NULL, NULL),
(285, 285, 'EN', 'KR', 'Do you want a paper pass or a phone pass?', '종이 패스와 휴대폰 패스 중 어떤 걸 원하세요?', 'https://d19azau1un4t7r.cloudfront.net/content/scenario-question-audio/285/b7940bdf01de62a32264a27b7910f3e25315cfb20f703a9a00b4a71dda61180a.mp3', 'ACTIVE', now(), now(), NULL, NULL),
